class AsyncBlockerResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def list(
        self,
        task: str,
        *,
        team: str | None = None,
        user: str | None = None,
        agent: str | None = None,
        org: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> BlockerListResponse:
        """
        List a task's blockers
        Returns a bounded page of the tasks currently marked as blocking the
        specified task, newest first. Blocking is informational: a blocked task
        can still change status, and it stops counting as blocked as soon as
        every blocker is done. The task's owner is resolved from the task itself.

        Args:
            task: Blocked task ID (`tsk_...`).
            team: Explicit owning team (`tem_...`) for privileged calls.
            user: Explicit owning user (`usr_...`) for privileged calls.
            agent: Explicit owning agent (`agi_...`) for privileged calls.
            org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            limit: Maximum blockers to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if team is not None:
            query["team"] = team
        if user is not None:
            query["user"] = user
        if agent is not None:
            query["agent"] = agent
        if org is not None:
            query["org"] = org
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/tasks/{task}/blockers",
            query=query,
            response_type=BlockerListResponse,
        )

    async def create(self, task: str, input: BlockerCreateInput) -> Task:
        """
        Mark a task as blocked by another task
        Records that the task in `blocker` blocks the specified task and returns
        the updated task. Blocking is informational the blocked task can still
        change status and derived at read time, so the task stops reporting
        `is_blocked` as soon as every blocker is done. The blocker must belong to
        the same owner (team or user) as the task; self-blocking and blocking a
        task that already blocks the blocker (a direct cycle) are rejected.

        Args:
            task: Blocked task ID (`tsk_...`).
            input: Request body.
            input.agent: Explicit owning agent (`agi_...`) for privileged calls.
            input.blocker: ID of the task that blocks this task (`tsk_...`).
            input.org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            input.team: Explicit owning team (`tem_...`) for privileged calls.
            input.user: Explicit owning user (`usr_...`) for privileged calls.

        Returns:
            The updated (blocked) task.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/blockers",
            method="POST",
            body=input,
            response_type=Task,
        )

    async def delete(self, task: str, blocker: str) -> None:
        """
        Remove a blocker from a task
        Removes the blocking relationship between the task in `blocker` and the
        specified task. Returns 204 No Content on success, or 404 if the given
        task is not currently marked as blocking this task.

        Args:
            task: Blocked task ID (`tsk_...`).
            blocker: ID of the blocking task to remove (`tsk_...`).

        Returns:
            Empty response body. HTTP 204 No Content on success.
        """
        await self._http.request(f"/api/v1/tasks/{task}/blockers/{blocker}", method="DELETE")


class AsyncCommentResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def list(
        self,
        task: str,
        *,
        team: str | None = None,
        user: str | None = None,
        agent: str | None = None,
        org: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> CommentListResponse:
        """
        List comments on a task
        Returns a bounded page of comments on the specified task, ordered by creation
        time ascending. App-scoped developer and server-to-server callers explicitly
        provide the owning `team`, `user`, or `agent` and `org`.

        Args:
            task: Task ID (`tsk_...`).
            team: Explicit owning team (`tem_...`) for privileged calls.
            user: Explicit owning user (`usr_...`) for privileged calls.
            agent: Explicit owning agent (`agi_...`) for privileged calls.
            org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            limit: Maximum comments to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if team is not None:
            query["team"] = team
        if user is not None:
            query["user"] = user
        if agent is not None:
            query["agent"] = agent
        if org is not None:
            query["org"] = org
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/tasks/{task}/comments",
            query=query,
            response_type=CommentListResponse,
        )

    async def create(self, task: str, input: CommentCreateInput) -> TaskComment:
        """
        Create a comment on a task
        Posts a new comment on the specified task and returns the created comment.
        The task's owner is resolved from the task itself.

        Args:
            task: Task ID (`tsk_...`).
            input: Request body.
            input.comment: Parameters for the comment to create, including its body.

        Returns:
            The newly created comment.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/comments",
            method="POST",
            body=input,
            response_type=TaskComment,
        )

    async def delete(self, task: str, comment: str) -> None:
        """
        Delete a task comment
        Permanently removes a comment from its task. This action cannot be undone.
        The task's owner is resolved from the task itself.
        Only the comment's author, an admin of the comment's organization, or an
        admin of the owning team may delete a comment. Returns `403 Forbidden`
        otherwise.

        Args:
            task: Task ID (`tsk_...`).
            comment: Comment ID (`tcm_...`).

        Returns:
            Empty body. The server responds with HTTP 204 No Content on success.
        """
        await self._http.request(f"/api/v1/tasks/{task}/comments/{comment}", method="DELETE")

    async def replace(self, task: str, comment: str, input: CommentReplaceInput) -> TaskComment:
        """
        Update a task comment
        Replaces the body of an existing comment and returns the updated comment.
        The task's owner is resolved from the task itself.
        Only the comment's author, an admin of the comment's organization, or an
        admin of the owning team may edit a comment. Returns `403 Forbidden`
        otherwise.

        Args:
            task: Task ID (`tsk_...`).
            comment: Comment ID (`tcm_...`).
            input: Request body.
            input.body: Replacement body for the comment. Must be non-empty.

        Returns:
            The updated comment.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/comments/{comment}",
            method="PUT",
            body=input,
            response_type=TaskComment,
        )


class AsyncLeaseResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def remove(self, task: str) -> None:
        """
        Release a task session lease
        Releases the authenticated assignee's matching live task lease. Repeating a
        release after the lease is absent succeeds. A different live successor lease
        returns a mismatch.

        Args:
            task: Task ID (`tsk_...`).

        Returns:
            Empty response. HTTP 204 is returned after release is accepted.
        """
        await self._http.request(f"/api/v1/tasks/{task}/lease", method="DELETE")

    async def list(self, task: str) -> TaskSessionLeaseSummary:
        """
        Retrieve a task's current session lease
        Returns the authenticated assignee's viewer-safe live lease summary, or null
        when no live lease exists. Fencing and opaque session identifiers are never
        included.

        Args:
            task: Task ID (`tsk_...`).

        Returns:
            Viewer-safe live lease summary, or null.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/lease",
            response_type=TaskSessionLeaseSummary,
        )

    async def create(self, task: str, input: LeaseCreateInput) -> TaskSessionLease:
        """
        Claim a task for a coding session
        Atomically claims a user-assigned task for the authenticated user's coding
        session. The caller generates and retains both UUIDs. An exact retry returns
        the existing lease without extending it; another live holder produces a
        conflict. Developer and server-to-server credentials cannot impersonate the
        assigned user.

        Args:
            task: Task ID (`tsk_...`).
            input: Request body.
            input.harness: Bounded harness identifier.
            input.lease_duration_seconds: Requested lease lifetime in seconds; the task aggregate enforces its bounds.
            input.lease_id: Caller-generated lease UUID.
            input.require_ready: Conservatively reject the claim when the current task projection has unfinished blockers.
            input.session_id: Caller-generated coding-session UUID.
            input.session_name: Human-readable coding-session label.

        Returns:
            The caller-held lease, including its fencing token.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/lease",
            method="POST",
            body=input,
            response_type=TaskSessionLease,
        )

    async def renew(self, task: str, input: LeaseRenewInput) -> TaskSessionLease:
        """
        Renew a task session lease
        Renews the authenticated assignee's matching live task lease. Both
        caller-generated UUIDs must match the aggregate's current lease.

        Args:
            task: Task ID (`tsk_...`).
            input: Request body.
            input.lease_duration_seconds: Requested renewed lifetime in seconds; the task aggregate enforces its bounds.
            input.lease_id: Current caller-held lease UUID.
            input.session_id: Current coding-session UUID.

        Returns:
            The renewed caller-held lease.
        """
        return await self._http.request(
            f"/api/v1/tasks/{task}/lease/renew",
            method="POST",
            body=input,
            response_type=TaskSessionLease,
        )


