class BlockerResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(
        self,
        task: str,
        *,
        team: str | None = None,
        user: str | None = None,
        agent: str | None = None,
        org: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> BlockerListResponse:
        """
        List a task's blockers
        Returns a bounded page of the tasks currently marked as blocking the
        specified task, newest first. Blocking is informational: a blocked task
        can still change status, and it stops counting as blocked as soon as
        every blocker is done. The task's owner is resolved from the task itself.

        Args:
            task: Blocked task ID (`tsk_...`).
            team: Explicit owning team (`tem_...`) for privileged calls.
            user: Explicit owning user (`usr_...`) for privileged calls.
            agent: Explicit owning agent (`agi_...`) for privileged calls.
            org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            limit: Maximum blockers to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if team is not None:
            query["team"] = team
        if user is not None:
            query["user"] = user
        if agent is not None:
            query["agent"] = agent
        if org is not None:
            query["org"] = org
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/tasks/{task}/blockers",
            query=query,
            response_type=BlockerListResponse,
        )

    def create(self, task: str, input: BlockerCreateInput) -> Task:
        """
        Mark a task as blocked by another task
        Records that the task in `blocker` blocks the specified task and returns
        the updated task. Blocking is informational the blocked task can still
        change status and derived at read time, so the task stops reporting
        `is_blocked` as soon as every blocker is done. The blocker must belong to
        the same owner (team or user) as the task; self-blocking and blocking a
        task that already blocks the blocker (a direct cycle) are rejected.

        Args:
            task: Blocked task ID (`tsk_...`).
            input: Request body.
            input.agent: Explicit owning agent (`agi_...`) for privileged calls.
            input.blocker: ID of the task that blocks this task (`tsk_...`).
            input.org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            input.team: Explicit owning team (`tem_...`) for privileged calls.
            input.user: Explicit owning user (`usr_...`) for privileged calls.

        Returns:
            The updated (blocked) task.
        """
        return self._http.request(
            f"/api/v1/tasks/{task}/blockers",
            method="POST",
            body=input,
            response_type=Task,
        )

    def delete(self, task: str, blocker: str) -> None:
        """
        Remove a blocker from a task
        Removes the blocking relationship between the task in `blocker` and the
        specified task. Returns 204 No Content on success, or 404 if the given
        task is not currently marked as blocking this task.

        Args:
            task: Blocked task ID (`tsk_...`).
            blocker: ID of the blocking task to remove (`tsk_...`).

        Returns:
            Empty response body. HTTP 204 No Content on success.
        """
        self._http.request(f"/api/v1/tasks/{task}/blockers/{blocker}", method="DELETE")


