class LeaseResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def remove(self, task: str) -> None:
        """
        Release a task session lease
        Releases the authenticated assignee's matching live task lease. Repeating a
        release after the lease is absent succeeds. A different live successor lease
        returns a mismatch.

        Args:
            task: Task ID (`tsk_...`).

        Returns:
            Empty response. HTTP 204 is returned after release is accepted.
        """
        self._http.request(f"/api/v1/tasks/{task}/lease", method="DELETE")

    def list(self, task: str) -> TaskSessionLeaseSummary:
        """
        Retrieve a task's current session lease
        Returns the authenticated assignee's viewer-safe live lease summary, or null
        when no live lease exists. Fencing and opaque session identifiers are never
        included.

        Args:
            task: Task ID (`tsk_...`).

        Returns:
            Viewer-safe live lease summary, or null.
        """
        return self._http.request(
            f"/api/v1/tasks/{task}/lease",
            response_type=TaskSessionLeaseSummary,
        )

    def create(self, task: str, input: LeaseCreateInput) -> TaskSessionLease:
        """
        Claim a task for a coding session
        Atomically claims a user-assigned task for the authenticated user's coding
        session. The caller generates and retains both UUIDs. An exact retry returns
        the existing lease without extending it; another live holder produces a
        conflict. Developer and server-to-server credentials cannot impersonate the
        assigned user.

        Args:
            task: Task ID (`tsk_...`).
            input: Request body.
            input.harness: Bounded harness identifier.
            input.lease_duration_seconds: Requested lease lifetime in seconds; the task aggregate enforces its bounds.
            input.lease_id: Caller-generated lease UUID.
            input.require_ready: Conservatively reject the claim when the current task projection has unfinished blockers.
            input.session_id: Caller-generated coding-session UUID.
            input.session_name: Human-readable coding-session label.

        Returns:
            The caller-held lease, including its fencing token.
        """
        return self._http.request(
            f"/api/v1/tasks/{task}/lease",
            method="POST",
            body=input,
            response_type=TaskSessionLease,
        )

    def renew(self, task: str, input: LeaseRenewInput) -> TaskSessionLease:
        """
        Renew a task session lease
        Renews the authenticated assignee's matching live task lease. Both
        caller-generated UUIDs must match the aggregate's current lease.

        Args:
            task: Task ID (`tsk_...`).
            input: Request body.
            input.lease_duration_seconds: Requested renewed lifetime in seconds; the task aggregate enforces its bounds.
            input.lease_id: Current caller-held lease UUID.
            input.session_id: Current coding-session UUID.

        Returns:
            The renewed caller-held lease.
        """
        return self._http.request(
            f"/api/v1/tasks/{task}/lease/renew",
            method="POST",
            body=input,
            response_type=TaskSessionLease,
        )


