    def subtasks(
        self,
        task: str,
        *,
        team: str | None = None,
        user: str | None = None,
        agent: str | None = None,
        org: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> TaskSubtasksResponse:
        """
        List a task's subtasks
        Returns a bounded page of the specified task's subtasks (tasks whose
        `parent` is this task), newest first. Subtasks nest exactly one level, so
        entries never have subtasks of their own. Privileged callers explicitly
        provide the owning `team`, `user`, or `agent` and `org`.

        Args:
            task: Parent task ID (`tsk_...`).
            team: Explicit owning team (`tem_...`) for privileged calls.
            user: Explicit owning user (`usr_...`) for privileged calls.
            agent: Explicit owning agent (`agi_...`) for privileged calls.
            org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
            limit: Maximum subtasks to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if team is not None:
            query["team"] = team
        if user is not None:
            query["user"] = user
        if agent is not None:
            query["agent"] = agent
        if org is not None:
            query["org"] = org
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/tasks/{task}/subtasks",
            query=query,
            response_type=TaskSubtasksResponse,
        )
